<script setup lang="ts">import {ref,computed,watch} from 'vue';import type {Workspace} from '../stores/workspace';import Heading from '../components/common/Heading.vue';import Empty from '../components/common/Empty.vue';import Status from '../components/common/Status.vue';import ScenarioStrip from '../components/ScenarioStrip.vue';import RiskSummary from '../components/RiskSummary.vue';import DagView from '../components/DagView.vue';import Histogram from '../components/Histogram.vue';import CriticalityBars from '../components/CriticalityBars.vue';import CrewSchedule from '../components/CrewSchedule.vue';import ResourceWait from '../components/ResourceWait.vue';import CpmTable from '../components/CpmTable.vue';import {num,short} from '../utils/format';const props=defineProps<{data:Workspace;selected:string}>();const id=ref(props.selected||'demo-run'),tab=ref('dag');watch(()=>props.selected,v=>{if(v)id.value=v});const run=computed(()=>props.data.runs.find(r=>r.id===id.value)||props.data.runs[0]);const result=computed(()=>run.value?.status==='completed'?run.value.result:null);const scenario=computed(()=>props.data.scenarios.find(s=>s.id===run.value?.scenario_id));watch(result,r=>{if(!r)return;if(r.resource){if(tab.value==='criticality')tab.value='schedule'}else if(tab.value==='schedule'||tab.value==='wait')tab.value='dag'});const titles:Record<string,string>={dag:'最可能工期·FS关键依赖',schedule:'班组受限·基线派工',distribution:'独立工期·完工样本',wait:'逐任务资源等待',criticality:'逐任务关键次数与分母'};</script><template><Heading index="05 / BASELINE & UNCERTAINTY" title="同一份依赖，两层时间证据。" detail="基线关键任务取最可能工期；模拟关键度逐次重算。配置班组的情景逐样本按容量与派工规则重算开工完工。所有图形均读取worker持久化结果。"/><label class="selector">选择推演运行<select aria-label="选择推演运行" v-model="id"><option v-for="r in data.runs" :key="r.id" :value="r.id">{{data.scenarios.find(s=>s.id===r.scenario_id)?.name}} · {{r.status}} · {{short(r.id)}}</option></select></label><Empty v-if="!run">在风险情景页提交一次后台推演，完成后在此查看DAG、时差和风险。</Empty><template v-else><div class="result-meta"><Status :value="run.status"/><span>RUN {{short(run.id)}}</span><span v-if="result">SHA256 {{short(result.checksum)}}</span></div><p v-if="run.status==='queued'||run.status==='running'" role="status" class="notice">后台正在逐次抽样并重算关键路径，完成后自动刷新。</p><p v-if="run.status==='failed'" role="alert" class="notice error">{{run.error}} · 调整输入后新建情景重试，失败记录保留。</p><template v-if="result"><ScenarioStrip v-if="scenario" :scenario="scenario"/><RiskSummary :result="result"/><div class="tabs"><button :class="{active:tab==='dag'}" @click="tab='dag'">CPM依赖图</button><button v-if="result.resource" :class="{active:tab==='schedule'}" @click="tab='schedule'">班组排程</button><button :class="{active:tab==='distribution'}" @click="tab='distribution'">工期分布</button><button v-if="result.resource" :class="{active:tab==='wait'}" @click="tab='wait'">资源等待</button><button v-else :class="{active:tab==='criticality'}" @click="tab='criticality'">任务关键度</button></div><section class="evidence-section"><h2>{{titles[tab]}}</h2><DagView v-if="tab==='dag'" :tasks="result.tasks" :edges="result.edges" :baseline="result.baseline"/><CrewSchedule v-else-if="tab==='schedule'&&result.resource" :plan="result.resource" :tasks="result.tasks"/><template v-else-if="tab==='distribution'"><Histogram :risk="result.risk"/><div class="quantiles"><span v-for="(v,k) in result.risk.quantiles" :key="k">{{k}} <b>{{num(v)}}h</b></span><span>均值 <b>{{num(result.risk.mean_finish)}}h</b></span></div><p class="muted">达标事件：项目完工≤{{result.risk.deadline}}小时 + {{result.risk.deadline_tolerance_hours}}小时浮点容差。{{result.resource?'完工样本为班组受限派工完工，已含资源等待；':''}}分位采用(n−1)q位置线性插值；有限样本结果，不是承诺。</p><details><summary>全部完工样本 / 小时</summary><p class="mono">{{result.risk.finish_times.map(v=>num(v,4)).join(' / ')}}</p></details></template><ResourceWait v-else-if="tab==='wait'&&result.resource" :risk="result.risk" :tasks="result.tasks"/><CriticalityBars v-else :risk="result.risk" :tasks="result.tasks"/></section><section><div class="section-rule"><h2>CPM前后向时刻 / 小时</h2><span>LF基准={{num(result.baseline.project_finish)}}h实际完工，外部deadline不参与{{result.resource?'；不计班组的参考时差，实际派工见班组排程':''}}</span></div><CpmTable :baseline="result.baseline" :tasks="result.tasks"/></section><details><summary>模型假设、快照校验和与边界</summary><p v-for="s in result.assumptions" :key="s">{{s}}</p><p class="mono">{{result.checksum}}</p><template v-if="result.resource"><div class="table-scroll"><table><thead><tr><th>班组</th><th>容量</th></tr></thead><tbody><tr v-for="c in result.resource.crews" :key="c.crew_id"><td><b>{{c.crew_id}}</b></td><td>{{c.capacity}}</td></tr></tbody></table></div><div class="table-scroll"><table><thead><tr><th>任务</th><th>优先级</th><th>占用班组</th></tr></thead><tbody><tr v-for="d in result.resource.dispatch" :key="d.task_id"><td><b>{{d.task_id}}</b></td><td>{{d.priority}}</td><td>{{Object.keys(d.crews).length?Object.entries(d.crews).map(([k,v])=>k+'×'+v).join(' '):'—'}}</td></tr></tbody></table></div></template><div class="table-scroll"><table><thead><tr><th>任务</th><th>a / m / b</th><th>alpha</th><th>beta</th><th>点质量</th></tr></thead><tbody><tr v-for="t in result.risk.ranges" :key="t.task_id"><td>{{t.task_id}}</td><td>{{t.a}} / {{t.m}} / {{t.b}}</td><td>{{t.alpha===null?'—':num(t.alpha,4)}}</td><td>{{t.beta===null?'—':num(t.beta,4)}}</td><td>{{t.point_mass?'是':'否'}}</td></tr></tbody></table></div></details></template></template></template>